import StorefrontHeader from "@/components/storefront/storefrontHeader";

/**
 * The storefront and account shell.
 *
 * One route group, not two. There was a separate (protected) group for the pages that need a
 * session, split because it carried its own header and its own auth gate — but two shells meant
 * two headers to keep in step and two places for a link to rot. The storefront has to stay
 * reachable without an account, so this shell stays guest-safe (its links never point somewhere a
 * guest would be redirected away from) and the per-page requirement moved into
 * components/auth-gate.tsx, applied by the pages that need it rather than inherited from a layout.
 */
export default function ShopLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <div className="min-h-screen bg-background">
      <StorefrontHeader />
      {children}
    </div>
  );
}